/* Prepared nonproduction patch: no profile payload/storage changes. */
#profile-modal { z-index:4000; padding:16px; }
#profile-modal > .modal-content {
  max-height:calc(100vh - 32px);
  max-height:calc(100dvh - 32px);
  scroll-padding-block:16px 80px;
  overscroll-behavior:contain;
}
#profile-modal .man-profile-actions {
  position:sticky; bottom:0; background:#fff; z-index:1;
  display:flex; flex-wrap:wrap; gap:10px; justify-content:flex-end;
  padding-block:12px max(12px, env(safe-area-inset-bottom, 0px));
}
#profile-modal .man-profile-actions button { min-height:44px; }
@media (max-width:900px) {
  #profile-modal { padding:8px; }
  #profile-modal > .modal-content {
    max-height:calc(100vh - 16px);
    max-height:calc(100dvh - 16px);
    padding:16px;
  }
}

