/* Maps existing Practice identities only after caller supplies explicit eligibility adjudication.
   Core completion != dictation completion; this boundary never changes scoring or awards from replay. */
(function(g){'use strict';
function adapt({uid,descriptor,snapshot,admission,eventId,receiptId,at,sentenceId,kind}){
 if(!uid||admission?.uid!==uid||admission?.accepted!==true||!admission.policyVersion)return {status:'PENDING_ELIGIBILITY_DECISION'};
 if(!descriptor?.identity?.lessonId||!descriptor.identity.lessonVersion||!snapshot||snapshot.phase!=='complete')return {status:'NOT_COMPLETE'};
 if(!['complete','active-review','practice'].includes(kind))return {status:'UNSUPPORTED_ACTIVITY'};
 if(kind==='active-review'&&(!sentenceId||!admission.activeReview))return {status:'PENDING_ACTIVE_REVIEW_IDENTITY'};
 if(kind==='active-review'&&!descriptor.playback.segments.some(s=>s.segmentId===sentenceId))return {status:'SENTENCE_IDENTITY_MISMATCH'};
 if(!eventId||!receiptId||typeof at!=='string'||!Number.isFinite(Date.parse(at)))return {status:'INVALID_RECEIPT'};
 return {status:'ADMITTED_NONPRODUCTION',event:{uid,kind,eligible:true,eventId,receiptId,at,lessonId:descriptor.identity.lessonId,version:descriptor.identity.lessonVersion,...(sentenceId?{sentenceId}:{})}};
}
const api={adapt};if(typeof module!=='undefined')module.exports=api;g.ManPracticeAchievementAdapter=api;
})(typeof globalThis==='undefined'?window:globalThis);

