/* Local/nonproduction integration. No history migration, network or trusted-public credential. */
(function(g){'use strict';
const A=typeof module!=='undefined'?require('./achievements.js'):g.ManAchievements;
class Integration {
 constructor({wishlist,achievements,storage,locks,now=()=>new Date().toISOString(),makeId=()=>g.crypto.randomUUID(),policy={},verifyEvidence=null,canMutate=()=>true}){Object.assign(this,{wishlist,achievements,storage,locks,now,makeId,policy,verifyEvidence,canMutate});}
 key(uid){return 'man_bc_save_proofs_v1_uid_'+uid;}
 proofs(uid){const raw=this.storage.getItem(this.key(uid));const doc=raw===null?{schema:1,uid,saves:[]}:JSON.parse(raw);if(doc.schema!==1||doc.uid!==uid||!Array.isArray(doc.saves)||doc.saves.some(e=>e.uid!==uid||e.kind!=='save'||!e.receiptId||!e.eventId||!e.lessonId||!e.version||!Number.isFinite(Date.parse(e.at))))throw Error('INVALID_SAVE_PROOFS');return doc;}
 async change(id,desired,context){
  if(!this.canMutate())return {status:'DELETION_BLOCKED'};
  if(!this.locks?.request)return {status:'CONCURRENCY_UNAVAILABLE'};
  return this.locks.request('man-bc:'+context.uid,{mode:'exclusive'},async()=>{
   if(!this.canMutate())return {status:'DELETION_BLOCKED'};
   const before=this.wishlist.read();if(before.uid!==context.uid||before.epoch!==context.epoch)return {status:'ACCOUNT_CHANGED'};
   let doc=null;try{doc=this.proofs(context.uid);}catch{/* Keep B usable; never overwrite an unreadable proof journal. */}
   const result=await this.wishlist.setSaved(id,desired,context);if(!result.ack)return result;
   const live=this.wishlist.read();if(live.uid!==context.uid||live.epoch!==context.epoch)return {status:'ACCOUNT_CHANGED'};
   if(!doc)return {...result,status:'PARTIAL_ACK',historyAck:false};
   if(desired&&!before.ids.includes(id)){
    const lesson=this.wishlist.catalog().find(u=>u.id===id);
    // Legacy/stale entries never create historic proof just because they are present.
    const op=this.makeId(),at=this.now();
    if(!lesson?.version||!Number.isFinite(Date.parse(at)))return {...result,status:'HISTORY_UNVERIFIABLE',historyAck:false};
    doc.saves.push({uid:context.uid,kind:'save',eligible:true,eventId:'save:'+op,receiptId:'local-save:'+op,lessonId:id,version:lesson.version,at});
    const raw=JSON.stringify(doc);if(raw.length>262144)return {...result,status:'PROOF_LIMIT',historyAck:false};
    try{this.storage.setItem(this.key(context.uid),raw);if(this.storage.getItem(this.key(context.uid))!==raw)throw Error('UNKNOWN');}catch{return {...result,status:'PARTIAL_ACK',historyAck:false};}
   }
   const proofAvailable=doc.saves.some(e=>e.lessonId===id);
   if(desired&&!proofAvailable)return {...result,status:'HISTORY_UNVERIFIABLE',historyAck:false,proofAvailable:false};
   return {...result,historyAck:true,proofAvailable};
  });
 }
 async reconcile(evidence){
  if(this.verifyEvidence&&!this.verifyEvidence(evidence))return {status:'EVIDENCE_NOT_ATTESTED'};
  const view=this.wishlist.read();if(view.status!=='LOCAL')return {status:view.status};
  if(evidence?.uid!==view.uid)return {status:'EVIDENCE_OWNER'};
  const old=this.achievements.read();if(old.status!=='LOCAL'||old.uid!==view.uid||old.epoch!==view.epoch)return {status:'ACHIEVEMENT_UNAVAILABLE'};
  let saves;try{saves=this.proofs(view.uid).saves;}catch{return {status:'PROOF_STORAGE_UNAVAILABLE'};}
  let result;try{result=A.evaluate({uid:view.uid,evidence:{...evidence,events:[...evidence.events,...saves]},wishlist:{uid:view.uid,ids:view.ids},previous:old.state,policy:this.policy});}catch{return {status:'UNVERIFIED_EVIDENCE'};}
  const write=await this.achievements.save(result.state,old);
  return {status:write.status,ack:write.ack===true,rows:write.ack?result.rows:null,rejected:result.rejected};
 }
 async equip(titleId){if(!this.canMutate())return {status:'DELETION_BLOCKED'};const old=this.achievements.read();if(old.status!=='LOCAL')return {status:old.status};try{return await this.achievements.save(A.equip(old.state,titleId),old);}catch{return {status:'TITLE_NOT_EARNED'};}}
}
const api={Integration};if(typeof module!=='undefined')module.exports=api;g.ManBC=api;
})(typeof globalThis==='undefined'?window:globalThis);

